//go:build googlepinyin && cgo && linux && !pinyin_external

package pinyinengine

import _ "embed"

// Generated by make from the pinned, checksummed upstream text corpus. The
// generated dictionary is gitignored, not a binary vendored into the repo.
//
//go:embed assets/dict_pinyin.dat
var dictionary []byte

func dictionaryBytes() ([]byte, error) { return dictionary, nil }
